134	    // linearRegression() over points[lo, hi) without copying them out
135	    static void fitRange(const std::vector<geometry_msgs::PointStamped>& points, size_t lo, size_t hi,
136	                         double& a, double& b, double& c)
137	    {
138	        LineAccumulator acc;
