145	    // A TF stamp of 0 means the chain was all static (fixedFrame_ rigidly attached to the
146	    // robot): the pose is then valid at any time, so stamp it with now().
147	    static ros::Time validStamp(const ros::Time& stamp)
148	    {
149	        return stamp.isZero() ? ros::Time::now() : stamp;
150	    }
151	
152	    // Stamp for a TF measured from a scan: the scan time, unless the lidar clock is not
153	    // synced with ROS time (then the scan stamp can't be used for TF lookups).
154	    static ros::Time scanTfStamp(const ros::Time& scanStamp)
155	    {
156	        ros::Time now = ros::Time::now();
157	        if (std::fabs((now - scanStamp).toSec()) > 1.0)
158	        {
159	            ROS_WARN_THROTTLE(5.0, "Scan stamp is %.2f s off ROS time, stamping with now()",
160	                              (now - scanStamp).toSec());
161	            return now;
162	        }
163	        return scanStamp;
164	    }
