166	    double DectectObject::distanceToLine(double x, double y, double a, double b, double c) {
167	        /*
168	            phuong trinh co dang ay = bx + c
169	        */
170	        return std::abs(a * y - b * x - c) / std::sqrt(a * a + b * b);
171	    }
