185	    void DectectObject::convertScanToPoint(const sensor_msgs::LaserScan& scan, std::vector<geometry_msgs::PointStamped>& points, std::string scanFrame)
186	    {
187	        float start_angle = scan.angle_min;
188	        float end_angle = scan.angle_max;
189	        float angle_increment = scan.angle_increment;
190	        const std::vector<float>& ranges = scan.ranges;
191	        points.reserve(points.size() + ranges.size());
192	
193	        for (int i = 0; i < ranges.size(); i++) {
194	            float range = ranges[i];
195	
196	            // Kiểm tra xem range có nằm trong khoảng hợp lệ không
197	            if (!std::isinf(range) && !std::isnan(range) && std::abs(range) > 0.1) {
198	                float angle = start_angle + i * angle_increment;
199	
200	                // Chuyển đổi tọa độ polar sang tọa độ Descartes
201	                float x = range * std::cos(angle);
202	                float y = range * std::sin(angle);
203	
204	                geometry_msgs::PointStamped point;
205	                point.point.x = x;
206	                point.point.y = y;
207	                point.header.frame_id = scanFrame;
208	
209	                // Thêm điểm vào vector points
210	                points.push_back(point);
211	            }
212	        }
213	    }
