215	    bool DectectObject::convertPointToNewFrame(const std::string& oldFrame, const std::string& newFrame,
216	                                    const std::vector<geometry_msgs::PointStamped>& oldPoints, std::vector<geometry_msgs::PointStamped>& newPoints)
217	    {
218	        geometry_msgs::TransformStamped transform_goal;
219	        try {
220	            transform_goal = tf_buffer_->lookupTransform(newFrame, oldFrame, ros::Time(0), ros::Duration(tfTimeout_));
221	        } catch (tf2::TransformException& ex) {
222	            ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
223	            return false;
224	        }
225	        newPoints.reserve(newPoints.size() + oldPoints.size());
226	        for (const geometry_msgs::PointStamped& point : oldPoints) {
227	            geometry_msgs::PointStamped transformed_point;
228	
229	            try {
230	                // Chuyển đổi điểm từ frame "lidar" sang frame "detect_link"
231	                tf2::doTransform(point, transformed_point, transform_goal);
232	                transformed_point.header.frame_id = frameRobot_;
233	
234	                newPoints.push_back(transformed_point);
235	            } catch (tf2::TransformException& ex) {
236	                ROS_ERROR("Lỗi biến đổi: %s", ex.what());
237	            }
238	        }
239	        return true;
240	    }
