242	    void DectectObject::removePointBehindOrFarRobot(std::vector<geometry_msgs::PointStamped>& points)
243	    {
244	        // remove_if + one erase: O(n) instead of erase() per point
245	        points.erase(std::remove_if(points.begin(), points.end(),
246	            [this](const geometry_msgs::PointStamped& p) {
247	                return (p.point.x < minDisPoint_ || std::abs(p.point.x) > maxDisPoint_) && std::abs(p.point.y) > 0.8;
248	            }), points.end());
249	    }
