251	    void DectectObject::filterPointMiddleRobot(std::vector<geometry_msgs::PointStamped>& points)
252	    {
253	        double sum_x = 0;
254	        double sum_y = 0;
255	        double average_x = 0;
256	        double average_y = 0;
257	
258	        points.erase(std::remove_if(points.begin(), points.end(),
259	            [this](const geometry_msgs::PointStamped& p) {
260	                return p.point.x < minDisPoint_ || std::abs(p.point.x) > maxDisPoint_ ||
261	                       std::abs(p.point.y) > disFilterMiddlePoint_;
262	            }), points.end());
263	
264	        if (points.empty())
265	            return;  // average below would divide by zero
266	
267	        for (auto it = points.begin(); it != points.end(); it++){
268	            sum_x += it->point.x;
269	            sum_y += it->point.y;
270	        }
271	        average_x = sum_x/points.size();
272	        average_y = sum_y/points.size();
273	
274	        points.erase(std::remove_if(points.begin(), points.end(),
275	            [average_x, average_y](const geometry_msgs::PointStamped& p) {
276	                return std::abs(p.point.x - average_x) > 1.0 || std::abs(p.point.y - average_y) > 1.0;
277	            }), points.end());
278	    }
