280	    bool DectectObject::comparePoints(const geometry_msgs::PointStamped& point1, const geometry_msgs::PointStamped& point2) {
281	        double angle1 = atan2(point1.point.x, point1.point.y);
282	        double angle2 = atan2(point2.point.x, point2.point.y);
283	        return angle1 < angle2;
284	    }
