286	    void DectectObject::sortByAngle(std::vector<geometry_msgs::PointStamped>& points)
287	    {
288	        std::vector<std::pair<double, size_t>> keys;
289	        keys.reserve(points.size());
290	        for (size_t i = 0; i < points.size(); i++) {
291	            keys.emplace_back(atan2(points[i].point.x, points[i].point.y), i);
292	        }
293	        std::sort(keys.begin(), keys.end(),
294	            [](const std::pair<double, size_t>& k1, const std::pair<double, size_t>& k2) {
295	                return k1.first < k2.first;
296	            });
297	
298	        std::vector<geometry_msgs::PointStamped> sorted;
299	        sorted.reserve(points.size());
300	        for (const auto& k : keys) {
301	            sorted.push_back(std::move(points[k.second]));
302	        }
303	        points.swap(sorted);
304	    }
