306	    bool DectectObject::arePerpendicular(double a1, double b1, double a2, double b2) {
307	        // Tích vô hướng của hai vector pháp tuyến
308	        double dotProduct = b1 * b2 + a1 * a2;
309	        // std::cout << "dotProduct: " << dotProduct << std::endl;
310	        return std::abs(dotProduct) < 0.15;
