313	    void DectectObject::detectLineGo()
314	    {
315	        std::vector<std::vector<geometry_msgs::PointStamped>> lines;
316	        double a,b,c;
317	        // Run once per new scan (scan1_ is filled by the subscriber in main's spinOnce)
318	        if (scan1Count_ == lineGoScan1Seen_)
319	            return;
320	        lineGoScan1Seen_ = scan1Count_;
321	
322	        std::vector<geometry_msgs::PointStamped> frameLaserPoints;
323	        std::vector<geometry_msgs::PointStamped> frameMiddleLaserPoints;
324	        convertScanToPoint(scan1_, frameLaserPoints, scan1Frame_);
325	        if (!convertPointToNewFrame(scan1Frame_, frameLaserMiddleRobot_, frameLaserPoints, frameMiddleLaserPoints))
326	            return;
327	        filterPointMiddleRobot(frameMiddleLaserPoints);
328	        sortByAngle(frameMiddleLaserPoints);
329	        std::vector<geometry_msgs::PointStamped> frameRobotPoints;
330	        if (!convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaserPoints, frameRobotPoints))
331	            return;
332	
333	        if (frameRobotPoints.size() < 20)
334	            return;
335	
336	        linearRegression(frameRobotPoints, a,b,c);
337	
338	        // kiem tra xem duong tao co thoa man hay khong
339	        int count_error = 0;
340	        for (auto i = 0; i < frameRobotPoints.size(); i ++)
341	        {
342	            double dis = distanceToLine(frameRobotPoints[i].point.x, frameRobotPoints[i].point.y, a, b, c);
343	            if (count_error > 5){
344	                return;
345	            }
346	
347	            if (dis > maxDiffCreatePath_){
348	                count_error += 1;
349	            }
350	        }
351	
352	        frameRobotPoints.front() = getProjectionCoordinates(frameRobotPoints.front(), a,b,c);
353	        frameRobotPoints.back() = getProjectionCoordinates(frameRobotPoints.back(), a,b,c);
354	
355	        geometry_msgs::PointStamped point_center;
356	        point_center = getPosCenter(frameRobotPoints.front(), frameRobotPoints.back());
357	        double angleWith0x = atan2(-a,b);
358	
359	        // get mid point in base_link frame
360	        geometry_msgs::TransformStamped transform_goal;
361	        geometry_msgs::PointStamped transformed_point;
362	        try {
363	            transform_goal = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
364	        } catch (tf2::TransformException& ex) {
365	            ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
366	            return;
367	        }
368	        tf2::doTransform(point_center, transformed_point, transform_goal);
369	
370	        // loc bot nhung diem ben ngoai
371	        if (std::abs(transformed_point.point.y) < 1.0)
372	        {
373	            // send frame of pallet
374	            static tf2_ros::TransformBroadcaster br1;
375	            geometry_msgs::TransformStamped transformStamped;
376	            // Measured in frameRobot_ at the scan time, not at now()
377	            transformStamped.header.stamp = scanTfStamp(scan1_.header.stamp);
378	            transformStamped.header.frame_id = frameRobot_;
379	            transformStamped.child_frame_id = frameLineGo_;
380	
381	            transformStamped.transform.translation.x = point_center.point.x;
382	            transformStamped.transform.translation.y = point_center.point.y;
383	            transformStamped.transform.translation.z = 0;
384	
385	            tf2::Quaternion q1;
386	            q1.setRPY(0, 0, angleWith0x);
387	            transformStamped.transform.rotation.x = q1.x();
388	            transformStamped.transform.rotation.y = q1.y();
389	            transformStamped.transform.rotation.z = q1.z();
390	            transformStamped.transform.rotation.w = q1.w();
391	            br1.sendTransform(transformStamped);
392	        }
393	    }
