395	    void DectectObject::detectDistanceTwoLine()
396	    {
397	        double a1,b1,c1;
398	        double a2,b2,c2;
399	        std_msgs::Float64 msgDis;
400	
401	        // Run once both lidars have delivered a new scan (was: block on waitForMessage for each)
402	        if (scan1Count_ == twoLineScan1Seen_ || scan2Count_ == twoLineScan2Seen_)
403	            return;
404	        twoLineScan1Seen_ = scan1Count_;
405	        twoLineScan2Seen_ = scan2Count_;
406	
407	        std::vector<geometry_msgs::PointStamped> frameLaser1Points;
408	        std::vector<geometry_msgs::PointStamped> frameLaser2Points;
409	        std::vector<geometry_msgs::PointStamped> frameMiddleLaser1Points;
410	        std::vector<geometry_msgs::PointStamped> frameMiddleLaser2Points;
411	        convertScanToPoint(scan1_, frameLaser1Points, scan1Frame_);
412	        convertScanToPoint(scan2_, frameLaser2Points, scan2Frame_);
413	        if (!convertPointToNewFrame(scan1Frame_, frameLaserMiddleRobot_, frameLaser1Points, frameMiddleLaser1Points) ||
414	            !convertPointToNewFrame(scan2Frame_, frameLaserMiddleRobot_, frameLaser2Points, frameMiddleLaser2Points))
415	            return;
416	
417	        filterPointMiddleRobot(frameMiddleLaser1Points);
418	        filterPointMiddleRobot(frameMiddleLaser2Points);
419	
420	        sortByAngle(frameMiddleLaser1Points);
421	        sortByAngle(frameMiddleLaser2Points);
422	        std::vector<geometry_msgs::PointStamped> frame1RobotPoints;
423	        std::vector<geometry_msgs::PointStamped> frame2RobotPoints;
424	        if (!convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaser1Points, frame1RobotPoints) ||
425	            !convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaser2Points, frame2RobotPoints))
426	            return;
427	
428	        if (frame1RobotPoints.size() < 20 || frame2RobotPoints.size() < 20){
429	            return;
430	        }
431	
432	        linearRegression(frame1RobotPoints, a1,b1,c1);
433	        linearRegression(frame2RobotPoints, a2,b2,c2);
434	        int count_error_1 = 0;
435	        int count_error_2 = 0;
436	
437	        for (auto i = 0; i < frame1RobotPoints.size(); i ++)
438	        {
439	            double dis = distanceToLine(frame1RobotPoints[i].point.x, frame1RobotPoints[i].point.y, a1, b1, c1);
440	            if (count_error_1 > 5){
441	                return;
442	            }
443	
444	            if (dis > maxDiffCreatePath_){
445	                count_error_1 += 1;
446	            }
447	        }
448	
449	        for (auto i = 0; i < frame2RobotPoints.size(); i ++)
450	        {
451	            double dis = distanceToLine(frame2RobotPoints[i].point.x, frame2RobotPoints[i].point.y, a2, b2, c2);
452	            if (count_error_2 > 5){
453	                return;
454	            }
455	
456	            if (dis > maxDiffCreatePath_){
457	                count_error_2 += 1;
458	            }
459	        }
460	        frame1RobotPoints.front() = getProjectionCoordinates(frame1RobotPoints.front(), a1,b1,c1);
461	        frame1RobotPoints.back() = getProjectionCoordinates(frame1RobotPoints.back(), a1,b1,c1);
462	        frame2RobotPoints.front() = getProjectionCoordinates(frame2RobotPoints.front(), a2,b2,c2);
463	        frame2RobotPoints.back() = getProjectionCoordinates(frame2RobotPoints.back(), a2,b2,c2);
464	        geometry_msgs::PointStamped point_center_1;
465	        geometry_msgs::PointStamped point_center_2;
466	        point_center_1 = getPosCenter(frame1RobotPoints.front(), frame1RobotPoints.back());
467	        point_center_2 = getPosCenter(frame2RobotPoints.front(), frame2RobotPoints.back());
468	        geometry_msgs::TransformStamped transform_goal;
469	        geometry_msgs::PointStamped transformed_point_1;
470	        geometry_msgs::PointStamped transformed_point_2;
471	        try {
472	            transform_goal = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
473	        } catch (tf2::TransformException& ex) {
474	            ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
475	            return;
476	        }
477	        tf2::doTransform(point_center_1, transformed_point_1, transform_goal);
478	        tf2::doTransform(point_center_2, transformed_point_2, transform_goal);
479	
480	        msgDis.data = transformed_point_1.point.x - transformed_point_2.point.x;
481	        distance_two_pallet_pub_.publish(msgDis);
482	    }
