#include <pick_and_place_pallet/detect_object.h>

namespace detect_object
{
    DectectObject::DectectObject(ros::NodeHandle nh): nh_(nh)
    {
        scan1Name_= nh_.param<std::string>("scan1_name", "/scan_map");
        scan2Name_= nh_.param<std::string>("scan2_name", "/scan_map");
        scan1Frame_= nh_.param<std::string>("scan1_frame", "laser");
        scan2Frame_= nh_.param<std::string>("scan2_frame", "laser");
        frameRobot_= nh_.param<std::string>("frame_robot", "tf_detect");
        framePallet_ = nh_.param<std::string>("frame_pallet", "tf_pallet");
        framePalletUnder_ = nh_.param<std::string>("frame_pallet_under", "tf_pallet_1_under");
        frameLaserMiddleRobot_ = nh_.param<std::string>("laser_middle_robot", "laser_middle_robot");
        frameLineGo_ = nh_.param<std::string>("frame_line_go", "tf_line_go");
        frameEdgePallet_ = nh_.param<std::string>("tf_edge", "tf_edge");

        maxDis_ = nh_.param<double>("max_distance_point_to_line", 0.018);
        minSizePath_ = nh_.param<int>("min_size_path", 20);
        maxDisPoint_= nh_.param<double>("max_distance_scan", 4.0);
        minDisPoint_= nh_.param<double>("min_distance_scan", 0.1);
        disFilterMiddlePoint_ = nh_.param<double>("dis_filter_middle_point", 0.25);
        lenghtPallet_ = nh_.param<double>("lenght_of_pallet", 0.77);
        maxDiffLenght_ = nh_.param<double>("max_diff_lenght", 0.03);
        maxDiffCreatePath_ = nh_.param<double>("max_diff_create_path", 0.015);
        useFrameUnder_ = nh_.param<bool>("use_frame_under", false);
        useDetectLineGo_ = nh_.param<bool>("use_detect_line_go", false);
        useDetectTwoLine_ = nh.param<bool>("use_detect_two_line", false);
        useDetectPalletNormal_ = nh.param<bool>("use_detect_pallet_normal", false);
        useDetectSquareCorner_ = nh.param<bool>("use_detect_square_corner", false);
        publishEdgePallet_ = nh.param<bool>("publish_edge_pallet", false);

        use3d_ = nh.param<bool>("use_3d", false);
        framePallet3d_ = nh_.param<std::string>("frame_pallet_3d", "tf_pallet_3d");
        framePalletUnder3d_ = nh_.param<std::string>("frame_pallet_under_3d", "tf_pallet_1_under_3d");
        frameEdgePallet3d_ = nh_.param<std::string>("tf_edge_3d", "tf_edge_1_3d");
        frameLineGo3d_ = nh_.param<std::string>("frame_line_go_3d", "tf_line_go_1_3d");
        fixedFrame_ = nh_.param<std::string>("fixed_frame", "odom");

        // ===== Output TF filter params (see detect_object.h Pose2DFilter) =====
        filterEnable_ = nh_.param<bool>("filter_enable", true);
        kfProcessNoisePos_ = nh_.param<double>("kf_process_noise_pos", 1e-4);
        kfMeasNoisePos_ = nh_.param<double>("kf_measurement_noise_pos", 4e-4);
        kfProcessNoiseYaw_ = nh_.param<double>("kf_process_noise_yaw", pow(2.0 * M_PI / 180.0, 2));
        kfMeasNoiseYaw_ = nh_.param<double>("kf_measurement_noise_yaw", pow(3.0 * M_PI / 180.0, 2));
        kfMotionNoisePos_ = nh_.param<double>("kf_motion_noise_pos", 0.0);
        kfMotionNoiseYaw_ = nh_.param<double>("kf_motion_noise_yaw", 0.0);
        filterGatePos_ = nh_.param<double>("filter_gate_pos", 0.08);
        filterGateYaw_ = nh_.param<double>("filter_gate_deg", 8.0) * M_PI / 180.0;
        filterMaxRejects_ = nh_.param<int>("filter_max_rejects", 5);
        filterResetTimeout_ = nh_.param<double>("filter_reset_timeout", 1.0);

        tfTimeout_ = nh_.param<double>("tf_timeout", 0.05);
        maxTfAge_ = nh_.param<double>("max_tf_age", 0.5);

        subScanDetect1_ = nh_.subscribe(scan1Name_, 1, &DectectObject::scanDetect1CB, this);
        if (useDetectTwoLine_)
        {
            subScanDetect2_ = nh_.subscribe(scan2Name_, 1, &DectectObject::scanDetect2CB, this);
        }

        marker_array_pub_ = nh_.advertise<visualization_msgs::MarkerArray>("marker_detect_object", 10);
        distance_two_pallet_pub_ = nh_.advertise<std_msgs::Float64>("distance_two_pallet", 10);
        distance_two_pallet_pub3d_ = nh_.advertise<std_msgs::Float64>("distance_two_pallet_3d", 10);

        tf_buffer_.reset(new tf2_ros::Buffer);
        tf_listener_.reset(new tf2_ros::TransformListener(*tf_buffer_));
    }

