        // }

        // for (const geometry_msgs::PointStamped& p : points) {
        //     YA = true;
        //     if (p.point.y != Ylog)
        //     {
        //         YA = false;
        //         break;
        //     }
        // }

        // if (XA == true){
        //     a = 0;
