    // linearRegression() over points[lo, hi) without copying them out
    static void fitRange(const std::vector<geometry_msgs::PointStamped>& points, size_t lo, size_t hi,
                         double& a, double& b, double& c)
    {
        LineAccumulator acc;
        for (size_t i = lo; i < hi; i++) {
            acc.add(points[i]);
        }
        acc.fit(a, b, c);
    }

    // A TF stamp of 0 means the chain was all static (fixedFrame_ rigidly attached to the
    // robot): the pose is then valid at any time, so stamp it with now().
    static ros::Time validStamp(const ros::Time& stamp)
    {
        return stamp.isZero() ? ros::Time::now() : stamp;
    }

    // Stamp for a TF measured from a scan: the scan time, unless the lidar clock is not
    // synced with ROS time (then the scan stamp can't be used for TF lookups).
    static ros::Time scanTfStamp(const ros::Time& scanStamp)
    {
        ros::Time now = ros::Time::now();
        if (std::fabs((now - scanStamp).toSec()) > 1.0)
        {
            ROS_WARN_THROTTLE(5.0, "Scan stamp is %.2f s off ROS time, stamping with now()",
                              (now - scanStamp).toSec());
            return now;
        }
        return scanStamp;
    }

    double DectectObject::distanceToLine(double x, double y, double a, double b, double c) {
        /*
            phuong trinh co dang ay = bx + c
        */
        return std::abs(a * y - b * x - c) / std::sqrt(a * a + b * b);
    }

    void DectectObject::scanDetect1CB(const sensor_msgs::LaserScan::ConstPtr& msg)
    {
        scan1_ = *msg;
        scan1Count_++;
    }

    void DectectObject::scanDetect2CB(const sensor_msgs::LaserScan::ConstPtr& msg)
    {
        scan2_ = *msg;
        scan2Count_++;
    }

    void DectectObject::convertScanToPoint(const sensor_msgs::LaserScan& scan, std::vector<geometry_msgs::PointStamped>& points, std::string scanFrame)
    {
        float start_angle = scan.angle_min;
        float end_angle = scan.angle_max;
        float angle_increment = scan.angle_increment;
        const std::vector<float>& ranges = scan.ranges;
        points.reserve(points.size() + ranges.size());

        for (int i = 0; i < ranges.size(); i++) {
            float range = ranges[i];

            // Kiểm tra xem range có nằm trong khoảng hợp lệ không
            if (!std::isinf(range) && !std::isnan(range) && std::abs(range) > 0.1) {
                float angle = start_angle + i * angle_increment;

                // Chuyển đổi tọa độ polar sang tọa độ Descartes
                float x = range * std::cos(angle);
                float y = range * std::sin(angle);

                geometry_msgs::PointStamped point;
                point.point.x = x;
                point.point.y = y;
                point.header.frame_id = scanFrame;

                // Thêm điểm vào vector points
                points.push_back(point);
            }
        }
    }

    bool DectectObject::convertPointToNewFrame(const std::string& oldFrame, const std::string& newFrame,
                                    const std::vector<geometry_msgs::PointStamped>& oldPoints, std::vector<geometry_msgs::PointStamped>& newPoints)
    {
        geometry_msgs::TransformStamped transform_goal;
        try {
            transform_goal = tf_buffer_->lookupTransform(newFrame, oldFrame, ros::Time(0), ros::Duration(tfTimeout_));
        } catch (tf2::TransformException& ex) {
            ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
            return false;
        }
        newPoints.reserve(newPoints.size() + oldPoints.size());
        for (const geometry_msgs::PointStamped& point : oldPoints) {
            geometry_msgs::PointStamped transformed_point;

            try {
                // Chuyển đổi điểm từ frame "lidar" sang frame "detect_link"
                tf2::doTransform(point, transformed_point, transform_goal);
                transformed_point.header.frame_id = frameRobot_;

                newPoints.push_back(transformed_point);
            } catch (tf2::TransformException& ex) {
                ROS_ERROR("Lỗi biến đổi: %s", ex.what());
            }
        }
        return true;
    }

    void DectectObject::removePointBehindOrFarRobot(std::vector<geometry_msgs::PointStamped>& points)
    {
        // remove_if + one erase: O(n) instead of erase() per point
        points.erase(std::remove_if(points.begin(), points.end(),
            [this](const geometry_msgs::PointStamped& p) {
                return (p.point.x < minDisPoint_ || std::abs(p.point.x) > maxDisPoint_) && std::abs(p.point.y) > 0.8;
            }), points.end());
    }

    void DectectObject::filterPointMiddleRobot(std::vector<geometry_msgs::PointStamped>& points)
    {
        double sum_x = 0;
        double sum_y = 0;
        double average_x = 0;
        double average_y = 0;

        points.erase(std::remove_if(points.begin(), points.end(),
            [this](const geometry_msgs::PointStamped& p) {
                return p.point.x < minDisPoint_ || std::abs(p.point.x) > maxDisPoint_ ||
                       std::abs(p.point.y) > disFilterMiddlePoint_;
            }), points.end());

        if (points.empty())
            return;  // average below would divide by zero

        for (auto it = points.begin(); it != points.end(); it++){
            sum_x += it->point.x;
            sum_y += it->point.y;
        }
        average_x = sum_x/points.size();
        average_y = sum_y/points.size();

        points.erase(std::remove_if(points.begin(), points.end(),
            [average_x, average_y](const geometry_msgs::PointStamped& p) {
                return std::abs(p.point.x - average_x) > 1.0 || std::abs(p.point.y - average_y) > 1.0;
            }), points.end());
    }

    bool DectectObject::comparePoints(const geometry_msgs::PointStamped& point1, const geometry_msgs::PointStamped& point2) {
        double angle1 = atan2(point1.point.x, point1.point.y);
        double angle2 = atan2(point2.point.x, point2.point.y);
        return angle1 < angle2;
    }

    void DectectObject::sortByAngle(std::vector<geometry_msgs::PointStamped>& points)
    {
        std::vector<std::pair<double, size_t>> keys;
        keys.reserve(points.size());
        for (size_t i = 0; i < points.size(); i++) {
            keys.emplace_back(atan2(points[i].point.x, points[i].point.y), i);
        }
        std::sort(keys.begin(), keys.end(),
            [](const std::pair<double, size_t>& k1, const std::pair<double, size_t>& k2) {
                return k1.first < k2.first;
            });

        std::vector<geometry_msgs::PointStamped> sorted;
        sorted.reserve(points.size());
        for (const auto& k : keys) {
            sorted.push_back(std::move(points[k.second]));
        }
        points.swap(sorted);
    }

    bool DectectObject::arePerpendicular(double a1, double b1, double a2, double b2) {
        // Tích vô hướng của hai vector pháp tuyến
        double dotProduct = b1 * b2 + a1 * a2;
        // std::cout << "dotProduct: " << dotProduct << std::endl;
        return std::abs(dotProduct) < 0.15;
    }

    void DectectObject::detectLineGo()
    {
        std::vector<std::vector<geometry_msgs::PointStamped>> lines;
        double a,b,c;
        // Run once per new scan (scan1_ is filled by the subscriber in main's spinOnce)
        if (scan1Count_ == lineGoScan1Seen_)
            return;
        lineGoScan1Seen_ = scan1Count_;

        std::vector<geometry_msgs::PointStamped> frameLaserPoints;
        std::vector<geometry_msgs::PointStamped> frameMiddleLaserPoints;
        convertScanToPoint(scan1_, frameLaserPoints, scan1Frame_);
        if (!convertPointToNewFrame(scan1Frame_, frameLaserMiddleRobot_, frameLaserPoints, frameMiddleLaserPoints))
            return;
        filterPointMiddleRobot(frameMiddleLaserPoints);
        sortByAngle(frameMiddleLaserPoints);
        std::vector<geometry_msgs::PointStamped> frameRobotPoints;
        if (!convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaserPoints, frameRobotPoints))
            return;

        if (frameRobotPoints.size() < 20)
            return;

        linearRegression(frameRobotPoints, a,b,c);

        // kiem tra xem duong tao co thoa man hay khong
        int count_error = 0;
        for (auto i = 0; i < frameRobotPoints.size(); i ++)
        {
            double dis = distanceToLine(frameRobotPoints[i].point.x, frameRobotPoints[i].point.y, a, b, c);
            if (count_error > 5){
                return;
            }

            if (dis > maxDiffCreatePath_){
                count_error += 1;
            }
        }

        frameRobotPoints.front() = getProjectionCoordinates(frameRobotPoints.front(), a,b,c);
        frameRobotPoints.back() = getProjectionCoordinates(frameRobotPoints.back(), a,b,c);

        geometry_msgs::PointStamped point_center;
        point_center = getPosCenter(frameRobotPoints.front(), frameRobotPoints.back());
        double angleWith0x = atan2(-a,b);

        // get mid point in base_link frame
        geometry_msgs::TransformStamped transform_goal;
        geometry_msgs::PointStamped transformed_point;
        try {
            transform_goal = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
        } catch (tf2::TransformException& ex) {
            ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
            return;
        }
        tf2::doTransform(point_center, transformed_point, transform_goal);

        // loc bot nhung diem ben ngoai
        if (std::abs(transformed_point.point.y) < 1.0)
        {
            // send frame of pallet
            static tf2_ros::TransformBroadcaster br1;
            geometry_msgs::TransformStamped transformStamped;
            // Measured in frameRobot_ at the scan time, not at now()
            transformStamped.header.stamp = scanTfStamp(scan1_.header.stamp);
            transformStamped.header.frame_id = frameRobot_;
            transformStamped.child_frame_id = frameLineGo_;

            transformStamped.transform.translation.x = point_center.point.x;
            transformStamped.transform.translation.y = point_center.point.y;
            transformStamped.transform.translation.z = 0;

            tf2::Quaternion q1;
            q1.setRPY(0, 0, angleWith0x);
            transformStamped.transform.rotation.x = q1.x();
            transformStamped.transform.rotation.y = q1.y();
            transformStamped.transform.rotation.z = q1.z();
            transformStamped.transform.rotation.w = q1.w();
            br1.sendTransform(transformStamped);
        }
    }

    void DectectObject::detectDistanceTwoLine()
    {
        double a1,b1,c1;
        double a2,b2,c2;
        std_msgs::Float64 msgDis;

        // Run once both lidars have delivered a new scan (was: block on waitForMessage for each)
        if (scan1Count_ == twoLineScan1Seen_ || scan2Count_ == twoLineScan2Seen_)
            return;
        twoLineScan1Seen_ = scan1Count_;
        twoLineScan2Seen_ = scan2Count_;

        std::vector<geometry_msgs::PointStamped> frameLaser1Points;
        std::vector<geometry_msgs::PointStamped> frameLaser2Points;
        std::vector<geometry_msgs::PointStamped> frameMiddleLaser1Points;
        std::vector<geometry_msgs::PointStamped> frameMiddleLaser2Points;
        convertScanToPoint(scan1_, frameLaser1Points, scan1Frame_);
        convertScanToPoint(scan2_, frameLaser2Points, scan2Frame_);
        if (!convertPointToNewFrame(scan1Frame_, frameLaserMiddleRobot_, frameLaser1Points, frameMiddleLaser1Points) ||
            !convertPointToNewFrame(scan2Frame_, frameLaserMiddleRobot_, frameLaser2Points, frameMiddleLaser2Points))
            return;

        filterPointMiddleRobot(frameMiddleLaser1Points);
        filterPointMiddleRobot(frameMiddleLaser2Points);

        sortByAngle(frameMiddleLaser1Points);
        sortByAngle(frameMiddleLaser2Points);
        std::vector<geometry_msgs::PointStamped> frame1RobotPoints;
        std::vector<geometry_msgs::PointStamped> frame2RobotPoints;
        if (!convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaser1Points, frame1RobotPoints) ||
            !convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaser2Points, frame2RobotPoints))
            return;

        if (frame1RobotPoints.size() < 20 || frame2RobotPoints.size() < 20){
            return;
        }

        linearRegression(frame1RobotPoints, a1,b1,c1);
        linearRegression(frame2RobotPoints, a2,b2,c2);
        int count_error_1 = 0;
        int count_error_2 = 0;

        for (auto i = 0; i < frame1RobotPoints.size(); i ++)
        {
            double dis = distanceToLine(frame1RobotPoints[i].point.x, frame1RobotPoints[i].point.y, a1, b1, c1);
            if (count_error_1 > 5){
                return;
            }

            if (dis > maxDiffCreatePath_){
                count_error_1 += 1;
            }
        }

        for (auto i = 0; i < frame2RobotPoints.size(); i ++)
        {
            double dis = distanceToLine(frame2RobotPoints[i].point.x, frame2RobotPoints[i].point.y, a2, b2, c2);
            if (count_error_2 > 5){
                return;
            }

            if (dis > maxDiffCreatePath_){
                count_error_2 += 1;
            }
        }
        frame1RobotPoints.front() = getProjectionCoordinates(frame1RobotPoints.front(), a1,b1,c1);
        frame1RobotPoints.back() = getProjectionCoordinates(frame1RobotPoints.back(), a1,b1,c1);
        frame2RobotPoints.front() = getProjectionCoordinates(frame2RobotPoints.front(), a2,b2,c2);
        frame2RobotPoints.back() = getProjectionCoordinates(frame2RobotPoints.back(), a2,b2,c2);
        geometry_msgs::PointStamped point_center_1;
        geometry_msgs::PointStamped point_center_2;
        point_center_1 = getPosCenter(frame1RobotPoints.front(), frame1RobotPoints.back());
        point_center_2 = getPosCenter(frame2RobotPoints.front(), frame2RobotPoints.back());
        geometry_msgs::TransformStamped transform_goal;
        geometry_msgs::PointStamped transformed_point_1;
        geometry_msgs::PointStamped transformed_point_2;
        try {
            transform_goal = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
        } catch (tf2::TransformException& ex) {
            ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
            return;
        }
        tf2::doTransform(point_center_1, transformed_point_1, transform_goal);
        tf2::doTransform(point_center_2, transformed_point_2, transform_goal);

        msgDis.data = transformed_point_1.point.x - transformed_point_2.point.x;
        distance_two_pallet_pub_.publish(msgDis);
    }

