814	                }
815	                else if(count < 2 && i+n+k < frameRobotPoints.size() - 1){
816	                    count +=1;
817	                }
818	                else{
819	                    if (points.size() < minSizePath_){
820	                        m = 1;
821	                        break;
822	                    }
823	                    else{
824	                        m = k + n - 2;
825	                        lines.push_back(std::move(points));
826	                        break;
827	                    }
828	                }
829	            }
830	        }
831	        return true;
832	    }
