843	    geometry_msgs::PointStamped DectectObject::getPosCenter(const geometry_msgs::PointStamped& point1, const geometry_msgs::PointStamped& point2)
844	    {
845	        geometry_msgs::PointStamped point;
846	        point.point.x = (point1.point.x + point2.point.x)/2;
847	        point.point.y = (point1.point.y + point2.point.y)/2;
