851	    geometry_msgs::PointStamped DectectObject::getProjectionCoordinates(const geometry_msgs::PointStamped& point, double a, double b , double c)
852	    {
853	        geometry_msgs::PointStamped pointGoal;
854	        pointGoal.point.x = (a*a*point.point.x + a*b*point.point.y - b*c)/(a*a + b*b);
855	        pointGoal.point.y = (b * pointGoal.point.x + c)/a;
856	        return pointGoal;
857	    }
858	
859	    // Gated constant-position Kalman filter on a planar pose. x, y, yaw are overwritten
860	    // with the filtered values. One bad line fit (gate) is held at the last good estimate
861	    // instead of jumping the control loop; filterMaxRejects_ in a row is treated as the
862	    // pallet having genuinely moved and the filter snaps to it. After filterResetTimeout_
863	    // seconds with no call (e.g. detection was disabled) the filter re-initializes fresh.
864	    void DectectObject::filterPose2D(Pose2DFilter& filter, double& x, double& y, double& yaw, const ros::Time& stamp,
865	                                     double extraPos, double extraYaw)
866	    {
867	        if (!filterEnable_) return;
868	
869	        if (!filter.valid || (stamp - filter.lastTime).toSec() > filterResetTimeout_)
870	        {
871	            filter.fx.reset(x, kfMeasNoisePos_);
872	            filter.fy.reset(y, kfMeasNoisePos_);
873	            filter.fyaw.reset(yaw, kfMeasNoiseYaw_);
874	            filter.lastTime = stamp;
875	            filter.valid = true;
876	            filter.rejects = 0;
877	            return;
878	        }
879	
880	        // Unwrap the measured yaw onto the branch nearest the current estimate so a
881	        // measurement near +-pi doesn't look like a huge jump.
882	        double yawMeas = filter.fyaw.x + atan2(sin(yaw - filter.fyaw.x), cos(yaw - filter.fyaw.x));
883	
884	        double dPos = std::hypot(x - filter.fx.x, y - filter.fy.x);
885	        double dYaw = std::fabs(yawMeas - filter.fyaw.x);
886	
887	        if (dPos > filterGatePos_ || dYaw > filterGateYaw_)
888	        {
889	            filter.rejects++;
890	            if (filter.rejects < filterMaxRejects_)
891	            {
892	                // Outlier: hold the last good estimate rather than pass the jump through.
893	                x = filter.fx.x;
894	                y = filter.fy.x;
895	                yaw = filter.fyaw.x;
896	                return;
897	            }
898	            // Persistent change -> the pallet really is elsewhere, re-init at the new pose.
899	            filter.fx.reset(x, kfMeasNoisePos_);
900	            filter.fy.reset(y, kfMeasNoisePos_);
901	            filter.fyaw.reset(yaw, kfMeasNoiseYaw_);
902	            filter.lastTime = stamp;
903	            filter.rejects = 0;
904	            return;
905	        }
906	
907	        double dt = std::max((stamp - filter.lastTime).toSec(), 1e-3);
908	        // update() adds q * dt, so the extra variance goes in as extra / dt
909	        x = filter.fx.update(x, dt, kfProcessNoisePos_ + extraPos / dt, kfMeasNoisePos_);
910	        y = filter.fy.update(y, dt, kfProcessNoisePos_ + extraPos / dt, kfMeasNoisePos_);
911	        yaw = filter.fyaw.update(yawMeas, dt, kfProcessNoiseYaw_ + extraYaw / dt, kfMeasNoiseYaw_);
912	        filter.lastTime = stamp;
913	        filter.rejects = 0;
914	    }
