916	    FixedFrameLink DectectObject::lookupFixedFrameLink(const ros::Time& scanStamp)
917	    {
918	        FixedFrameLink link;
919	        link.outStamp = scanTfStamp(scanStamp);
920	        geometry_msgs::TransformStamped fixedFromRobot, robotFromFixed;
921	        try {
922	            try {
923	                fixedFromRobot = tf_buffer_->lookupTransform(fixedFrame_, frameRobot_, scanStamp, ros::Duration(tfTimeout_));
924	            } catch (tf2::TransformException& ex) {
925	                // Scan newer than the latest odom (or clock offset): use the latest robot pose.
926	                // While moving this misplaces the pallet in fixedFrame_ by v * (odom - scan) time.
927	                ROS_WARN_THROTTLE(2.0, "No %s -> %s at scan time, using latest: %s",
928	                                  fixedFrame_.c_str(), frameRobot_.c_str(), ex.what());
929	                fixedFromRobot = tf_buffer_->lookupTransform(fixedFrame_, frameRobot_, ros::Time(0));
930	            }
931	            robotFromFixed = tf_buffer_->lookupTransform(frameRobot_, fixedFrame_, ros::Time(0));
932	        } catch (tf2::TransformException& ex) {
933	            ROS_WARN_THROTTLE(2.0, "No TF %s <-> %s, filtering in %s: %s",
934	                              fixedFrame_.c_str(), frameRobot_.c_str(), frameRobot_.c_str(), ex.what());
935	            return link;
936	        }
937	        tf2::fromMsg(fixedFromRobot.transform, link.fixedFromRobotScan);
938	        tf2::fromMsg(robotFromFixed.transform, link.robotNowFromFixed);
939	        // Output is re-expressed in the latest robot pose -> stamp with that pose's time
940	        link.outStamp = validStamp(robotFromFixed.header.stamp);
941	        link.valid = true;
942	        return link;
943	    }
944	
945	    // The bottom pallet is static in the world, not in frameRobot_: a constant-position
946	    // filter in the moving robot frame lags ~7.7 * v * dt behind and then snaps through the
947	    // gate. In fixedFrame_ (odom) it is really constant, so there is no motion lag; the
948	    // result is re-expressed in the robot's latest pose (also compensates processing delay).
949	    void DectectObject::filterPose2DInFixed(Pose2DFilter& filter, double& x, double& y, double& yaw,
950	                                            const ros::Time& scanStamp, const FixedFrameLink& link)
951	    {
952	        if (filter.inFixed != link.valid)
953	        {
954	            filter.valid = false;  // state is in the other frame -> re-init
955	            filter.inFixed = link.valid;
956	        }
957	        if (!link.valid)
958	        {
959	            filterPose2D(filter, x, y, yaw, scanStamp);
960	            return;
961	        }
962	
963	        tf2::Quaternion q;
964	        q.setRPY(0, 0, yaw);
965	        tf2::Transform fixedPose = link.fixedFromRobotScan * tf2::Transform(q, tf2::Vector3(x, y, 0.0));
966	        double fx = fixedPose.getOrigin().x();
967	        double fy = fixedPose.getOrigin().y();
968	        double fz = fixedPose.getOrigin().z();
969	        double fyaw = tf2::getYaw(fixedPose.getRotation());
970	
971	        // While the robot moves, scan/odom timing and odom error shift the measured pallet in
972	        // fixedFrame_, so the "static" state lags behind the line. Loosen the filter by how far
973	        // the robot moved since the last update; standing still keeps the full smoothing.
974	        double travel = 0.0;
975	        if (filter.hasLastRobot)
976	            travel = (link.fixedFromRobotScan.getOrigin() - filter.lastFixedFromRobot.getOrigin()).length();
977	        filter.lastFixedFromRobot = link.fixedFromRobotScan;
978	        filter.hasLastRobot = true;
979	
980	        filterPose2D(filter, fx, fy, fyaw, scanStamp, kfMotionNoisePos_ * travel, kfMotionNoiseYaw_ * travel);
981	
982	        q.setRPY(0, 0, fyaw);
983	        tf2::Transform robotPose = link.robotNowFromFixed * tf2::Transform(q, tf2::Vector3(fx, fy, fz));
984	        x = robotPose.getOrigin().x();
985	        y = robotPose.getOrigin().y();
986	        yaw = tf2::getYaw(robotPose.getRotation());
987	    }
