bool DectectObject::detectLine(std::vector<std::vector<geometry_msgs::PointStamped>>& lines, ros::Time& scanStamp)
{
    lines.clear();
    // Run once per new scan (scan1_ is filled by the subscriber in main's spinOnce)
    if (scan1Count_ == lineScan1Seen_)
        return false;
    lineScan1Seen_ = scan1Count_;
    scanStamp = scan1_.header.stamp;

    std::vector<geometry_msgs::PointStamped> frameLaserPoints;
    convertScanToPoint(scan1_, frameLaserPoints, scan1Frame_);
    removePointBehindOrFarRobot(frameLaserPoints);
    sortByAngle(frameLaserPoints);
    std::vector<geometry_msgs::PointStamped> frameRobotPoints;
    if (!convertPointToNewFrame(scan1Frame_, frameRobot_, frameLaserPoints, frameRobotPoints))
        return true;  // scan consumed, no lines
    // visualization_msgs::MarkerArray marker_array;
    // int unique_id = 0;
    // for (auto i = 0; i < frameRobotPoints.size(); i++)
    // {
    //     visualization_msgs::Marker marker;
    //     marker.header.frame_id = frameRobot_;  // Thay thế "your_frame_id" bằng tên frame của bạn
    //     marker.header.stamp = ros::Time();
    //     marker.ns = "detect_object";  // Thay thế "your_namespace" bằng tên namespace của bạn
    //     marker.id = unique_id;  // Thay thế unique_id bằng một giá trị duy nhất cho mỗi marker
    //     marker.type = visualization_msgs::Marker::SPHERE;
    //     marker.action = visualization_msgs::Marker::ADD;
    //     marker.pose.position.x = frameRobotPoints[i].point.x;
    //     marker.pose.position.y = frameRobotPoints[i].point.y;
    //     marker.pose.position.z = 0;
    //     marker.scale.x = 0.05;  // Điều chỉnh kích thước marker theo nhu cầu
    //     marker.scale.y = 0.05;
    //     marker.scale.z = 0.05;
    //     marker.color.a = 1.0;
    //     marker.color.r = 1.0;
    //     marker.color.g = 0.0;
    //     marker.color.b = 0.0;
    //     marker_array.markers.push_back(marker);
    //     unique_id++;  // Tăng unique_id cho mỗi marker
    // }
    // marker_array_pub_.publish(marker_array);
    // removePointBehindOrFarRobot(frameRobotPoints);

    int n = minSizePath_/2;
    int m = 1;
    if (n < 1 || frameRobotPoints.size() < n)
        return true;

    for (auto i = 0; i < frameRobotPoints.size() - n; i = i + m){
        double a,b,c;
        std::vector<geometry_msgs::PointStamped> points;
        // Running sums of `points`: same fit as linearRegression(points), but O(1)
        // per added point instead of re-summing the whole line each time
        LineAccumulator acc;
        // tao duong thang goc
        for (auto j = 0; j < n; j ++){
            points.push_back(frameRobotPoints[i+j]);
            acc.add(frameRobotPoints[i+j]);
        }
        acc.fit(a,b,c);

        // kiem tra xem duong tao co thoa man hay khong
        bool goodLine = true;
        for (auto j = 0; j < n; j ++)
        {
            double dis = distanceToLine(frameRobotPoints[i+j].point.x, frameRobotPoints[i+j].point.y, a, b, c);
            double dis_to_old_point = 0.0;
            if (j >= 1){
                dis_to_old_point = sqrt(pow((frameRobotPoints[i+j].point.x - frameRobotPoints[i+j-1].point.x),2)
                + pow((frameRobotPoints[i+j].point.y - frameRobotPoints[i+j-1].point.y),2));
            }
            if (dis > maxDiffCreatePath_ || std::abs(dis_to_old_point) > 0.05){
                goodLine = false;
            }

        }
        if (goodLine == false)
        {
            m = 1;
            continue;
        }
        /*
            tinh khoang cach tu cac diem tiep theo den duong thang da tao
            neu khoang cach nho hon khoang cach maxDis_ thi dua diem do vao de tao duong thang moi
            neu khong thi thoat vong lap vaf kiem tra so phan tu
            neu so phan tu lon hon ... thi coi do la duong thang
        */
        int count = 0;
        for (auto k = 0; k < frameRobotPoints.size() - i - n; k ++){
            double dis = distanceToLine(frameRobotPoints[i+n+k].point.x, frameRobotPoints[i+n+k].point.y, a, b, c);
            double dis_to_old_point = 0.0;
            if (k >= 1){
                dis_to_old_point = sqrt(pow((frameRobotPoints[i+n+k].point.x - frameRobotPoints[i+n+k-1].point.x),2)
                + pow((frameRobotPoints[i+n+k].point.y - frameRobotPoints[i+n+k-1].point.y),2));
            }
            if (dis < maxDis_ && std::abs(dis_to_old_point) < 0.05 && i+n+k < frameRobotPoints.size() -1){
                count = 0;
                points.push_back(frameRobotPoints[i+n+k]);
                acc.add(frameRobotPoints[i+n+k]);
                acc.fit(a,b,c);
            }
            // else if (abs(dis_to_old_point) > 0.05 && abs(frameRobotPoints[i+n+k].point.y) > 1.0)
            else if (std::abs(dis_to_old_point) > 0.05)
            {
                if (points.size() < minSizePath_){
                    m = 1;
                    break;
                }
                else{
                    m = k + n - 1;
                    lines.push_back(std::move(points));
                    break;
                }
            }
            else if(count < 2 && i+n+k < frameRobotPoints.size() - 1){
                count +=1;
            }
            else{
                if (points.size() < minSizePath_){
                    m = 1;
                    break;
                }
                else{
                    m = k + n - 2;
                    lines.push_back(std::move(points));
                    break;
                }
            }
        }
    }
    return true;
}


double DectectObject::getDistanceOf2Point(const geometry_msgs::PointStamped& point1, const geometry_msgs::PointStamped& point2)
{
    double dx = point1.point.x - point2.point.x;
    double dy = point1.point.y - point2.point.y;
    double dis = sqrt(dx*dx+dy*dy);
    return dis;
}

geometry_msgs::PointStamped DectectObject::getPosCenter(const geometry_msgs::PointStamped& point1, const geometry_msgs::PointStamped& point2)
{
    geometry_msgs::PointStamped point;
    point.point.x = (point1.point.x + point2.point.x)/2;
    point.point.y = (point1.point.y + point2.point.y)/2;
    return point;
}

geometry_msgs::PointStamped DectectObject::getProjectionCoordinates(const geometry_msgs::PointStamped& point, double a, double b , double c)
{
    geometry_msgs::PointStamped pointGoal;
    pointGoal.point.x = (a*a*point.point.x + a*b*point.point.y - b*c)/(a*a + b*b);
    pointGoal.point.y = (b * pointGoal.point.x + c)/a;
    return pointGoal;
}

// Gated constant-position Kalman filter on a planar pose. x, y, yaw are overwritten
// with the filtered values. One bad line fit (gate) is held at the last good estimate
// instead of jumping the control loop; filterMaxRejects_ in a row is treated as the
// pallet having genuinely moved and the filter snaps to it. After filterResetTimeout_
// seconds with no call (e.g. detection was disabled) the filter re-initializes fresh.
void DectectObject::filterPose2D(Pose2DFilter& filter, double& x, double& y, double& yaw, const ros::Time& stamp,
                                 double extraPos, double extraYaw)
{
    if (!filterEnable_) return;

    if (!filter.valid || (stamp - filter.lastTime).toSec() > filterResetTimeout_)
    {
        filter.fx.reset(x, kfMeasNoisePos_);
        filter.fy.reset(y, kfMeasNoisePos_);
        filter.fyaw.reset(yaw, kfMeasNoiseYaw_);
        filter.lastTime = stamp;
        filter.valid = true;
        filter.rejects = 0;
        return;
    }

    // Unwrap the measured yaw onto the branch nearest the current estimate so a
    // measurement near +-pi doesn't look like a huge jump.
    double yawMeas = filter.fyaw.x + atan2(sin(yaw - filter.fyaw.x), cos(yaw - filter.fyaw.x));

    double dPos = std::hypot(x - filter.fx.x, y - filter.fy.x);
    double dYaw = std::fabs(yawMeas - filter.fyaw.x);

    if (dPos > filterGatePos_ || dYaw > filterGateYaw_)
    {
        filter.rejects++;
        if (filter.rejects < filterMaxRejects_)
        {
            // Outlier: hold the last good estimate rather than pass the jump through.
            x = filter.fx.x;
            y = filter.fy.x;
            yaw = filter.fyaw.x;
            return;
        }
        // Persistent change -> the pallet really is elsewhere, re-init at the new pose.
        filter.fx.reset(x, kfMeasNoisePos_);
        filter.fy.reset(y, kfMeasNoisePos_);
        filter.fyaw.reset(yaw, kfMeasNoiseYaw_);
        filter.lastTime = stamp;
        filter.rejects = 0;
        return;
    }

    double dt = std::max((stamp - filter.lastTime).toSec(), 1e-3);
    // update() adds q * dt, so the extra variance goes in as extra / dt
    x = filter.fx.update(x, dt, kfProcessNoisePos_ + extraPos / dt, kfMeasNoisePos_);
    y = filter.fy.update(y, dt, kfProcessNoisePos_ + extraPos / dt, kfMeasNoisePos_);
    yaw = filter.fyaw.update(yawMeas, dt, kfProcessNoiseYaw_ + extraYaw / dt, kfMeasNoiseYaw_);
    filter.lastTime = stamp;
    filter.rejects = 0;
}

FixedFrameLink DectectObject::lookupFixedFrameLink(const ros::Time& scanStamp)
{
    FixedFrameLink link;
    link.outStamp = scanTfStamp(scanStamp);
    geometry_msgs::TransformStamped fixedFromRobot, robotFromFixed;
    try {
        try {
            fixedFromRobot = tf_buffer_->lookupTransform(fixedFrame_, frameRobot_, scanStamp, ros::Duration(tfTimeout_));
        } catch (tf2::TransformException& ex) {
            // Scan newer than the latest odom (or clock offset): use the latest robot pose.
            // While moving this misplaces the pallet in fixedFrame_ by v * (odom - scan) time.
            ROS_WARN_THROTTLE(2.0, "No %s -> %s at scan time, using latest: %s",
                              fixedFrame_.c_str(), frameRobot_.c_str(), ex.what());
            fixedFromRobot = tf_buffer_->lookupTransform(fixedFrame_, frameRobot_, ros::Time(0));
        }
        robotFromFixed = tf_buffer_->lookupTransform(frameRobot_, fixedFrame_, ros::Time(0));
    } catch (tf2::TransformException& ex) {
        ROS_WARN_THROTTLE(2.0, "No TF %s <-> %s, filtering in %s: %s",
                          fixedFrame_.c_str(), frameRobot_.c_str(), frameRobot_.c_str(), ex.what());
        return link;
    }
    tf2::fromMsg(fixedFromRobot.transform, link.fixedFromRobotScan);
    tf2::fromMsg(robotFromFixed.transform, link.robotNowFromFixed);
    // Output is re-expressed in the latest robot pose -> stamp with that pose's time
    link.outStamp = validStamp(robotFromFixed.header.stamp);
    link.valid = true;
    return link;
}

// The bottom pallet is static in the world, not in frameRobot_: a constant-position
// filter in the moving robot frame lags ~7.7 * v * dt behind and then snaps through the
// gate. In fixedFrame_ (odom) it is really constant, so there is no motion lag; the
// result is re-expressed in the robot's latest pose (also compensates processing delay).
void DectectObject::filterPose2DInFixed(Pose2DFilter& filter, double& x, double& y, double& yaw,
                                        const ros::Time& scanStamp, const FixedFrameLink& link)
{
    if (filter.inFixed != link.valid)
    {
        filter.valid = false;  // state is in the other frame -> re-init
        filter.inFixed = link.valid;
    }
    if (!link.valid)
    {
        filterPose2D(filter, x, y, yaw, scanStamp);
        return;
    }

    tf2::Quaternion q;
    q.setRPY(0, 0, yaw);
    tf2::Transform fixedPose = link.fixedFromRobotScan * tf2::Transform(q, tf2::Vector3(x, y, 0.0));
    double fx = fixedPose.getOrigin().x();
    double fy = fixedPose.getOrigin().y();
    double fz = fixedPose.getOrigin().z();
    double fyaw = tf2::getYaw(fixedPose.getRotation());

    // While the robot moves, scan/odom timing and odom error shift the measured pallet in
    // fixedFrame_, so the "static" state lags behind the line. Loosen the filter by how far
    // the robot moved since the last update; standing still keeps the full smoothing.
    double travel = 0.0;
    if (filter.hasLastRobot)
        travel = (link.fixedFromRobotScan.getOrigin() - filter.lastFixedFromRobot.getOrigin()).length();
    filter.lastFixedFromRobot = link.fixedFromRobotScan;
    filter.hasLastRobot = true;

    filterPose2D(filter, fx, fy, fyaw, scanStamp, kfMotionNoisePos_ * travel, kfMotionNoiseYaw_ * travel);

    q.setRPY(0, 0, fyaw);
    tf2::Transform robotPose = link.robotNowFromFixed * tf2::Transform(q, tf2::Vector3(fx, fy, fz));
    x = robotPose.getOrigin().x();
    y = robotPose.getOrigin().y();
    yaw = tf2::getYaw(robotPose.getRotation());
}

void DectectObject::detectObject()
{
    std::vector<std::vector<geometry_msgs::PointStamped>> lines;
    std::vector<detect_object::Line> dataLines;
    ros::Time scanStamp;
    if (!detectLine(lines, scanStamp))
        return;  // no new scan yet
    FixedFrameLink link;
    bool linkLooked = false;  // looked up once, on the first accepted line

    // Create marker array for visualization
    visualization_msgs::MarkerArray marker_array;
    int unique_id = 0;

    for (auto i = 0; i < lines.size(); i++)
    {
        // filter sensor because lidar 2 edge are noise
        // Trim on the index range [lo, hi) and erase once at the end, instead of
        // erase(begin()) per step. Each step still refits the remaining points from
        // scratch, so the trimmed line is exactly the same as before.
        std::vector<geometry_msgs::PointStamped>& pts = lines[i];
        size_t lo = 0, hi = pts.size();
        double a, b, c;
        while(hi - lo > 10)
        {
            fitRange(pts, lo, hi, a, b, c);
            if (distanceToLine(pts[lo].point.x, pts[lo].point.y, a, b, c) > 0.05)
            {
                lo++;
            }
            else{
                break;
            }
        }

        while(hi - lo > 10)
        {
            fitRange(pts, lo, hi, a, b, c);
            if (distanceToLine(pts[hi - 1].point.x, pts[hi - 1].point.y, a, b, c) > 0.05)
            {
                hi--;
            }
            else{
                break;
            }
        }
        pts.erase(pts.begin() + hi, pts.end());
        pts.erase(pts.begin(), pts.begin() + lo);

        detect_object::Line line;
        linearRegression(lines[i], line.a, line.b, line.c);
        line.firstPoint = lines[i].front();
        line.lastPoint = lines[i].back();

        // filter first point and last point
        // if dis to line is far get near point to create path
        line.firstPoint = getProjectionCoordinates(line.firstPoint, line.a, line.b, line.c);
        line.lastPoint = getProjectionCoordinates(line.lastPoint, line.a, line.b, line.c);
        dataLines.push_back(line);
        double disance = getDistanceOf2Point(line.firstPoint, line.lastPoint);

        // Visualize the detected line
        visualization_msgs::Marker line_marker;
        line_marker.header.frame_id = frameRobot_;
        line_marker.header.stamp = ros::Time::now();
        line_marker.ns = "detected_lines";
        line_marker.id = unique_id++;
        line_marker.type = visualization_msgs::Marker::LINE_STRIP;
        line_marker.action = visualization_msgs::Marker::ADD;
        line_marker.scale.x = 0.02;  // Line width
        line_marker.color.a = 1.0;
        line_marker.color.r = 0.0;
        line_marker.color.g = 1.0;
        line_marker.color.b = 0.0;

        geometry_msgs::Point p1, p2;
        p1.x = line.firstPoint.point.x;
        p1.y = line.firstPoint.point.y;
        p1.z = 0.0;
        p2.x = line.lastPoint.point.x;
        p2.y = line.lastPoint.point.y;
        p2.z = 0.0;
        line_marker.points.push_back(p1);
        line_marker.points.push_back(p2);
        marker_array.markers.push_back(line_marker);

        // Visualize the start point
        visualization_msgs::Marker start_marker;
        start_marker.header.frame_id = frameRobot_;
        start_marker.header.stamp = ros::Time::now();
        start_marker.ns = "line_start_points";
        start_marker.id = unique_id++;
        start_marker.type = visualization_msgs::Marker::SPHERE;
        start_marker.action = visualization_msgs::Marker::ADD;
        start_marker.pose.position.x = line.firstPoint.point.x;
        start_marker.pose.position.y = line.firstPoint.point.y;
        start_marker.pose.position.z = 0.0;
        start_marker.scale.x = 0.05;
        start_marker.scale.y = 0.05;
        start_marker.scale.z = 0.05;
        start_marker.color.a = 1.0;
        start_marker.color.r = 1.0;
        start_marker.color.g = 0.0;
        start_marker.color.b = 0.0;
        marker_array.markers.push_back(start_marker);

        // Visualize the end point
        visualization_msgs::Marker end_marker;
        end_marker.header.frame_id = frameRobot_;
        end_marker.header.stamp = ros::Time::now();
        end_marker.ns = "line_end_points";
        end_marker.id = unique_id++;
        end_marker.type = visualization_msgs::Marker::SPHERE;
        end_marker.action = visualization_msgs::Marker::ADD;
        end_marker.pose.position.x = line.lastPoint.point.x;
        end_marker.pose.position.y = line.lastPoint.point.y;
        end_marker.pose.position.z = 0.0;
        end_marker.scale.x = 0.05;
        end_marker.scale.y = 0.05;
        end_marker.scale.z = 0.05;
        end_marker.color.a = 1.0;
        end_marker.color.r = 0.0;
        end_marker.color.g = 0.0;
        end_marker.color.b = 1.0;
        marker_array.markers.push_back(end_marker);
        // std::cout << "disFirstPointToLine: " << disFirstPointToLine << std::endl;
        // std::cout << "disLastPointToLine: " << disLastPointToLine << std::endl;
        ROS_DEBUG("disance: %f", disance);


        if (std::abs(disance - lenghtPallet_) < maxDiffLenght_){
            geometry_msgs::PointStamped point_center;
            point_center = getPosCenter(line.firstPoint, line.lastPoint);
            double angleWith0x = atan2(-line.a,line.b);

            // get mid point in base_link frame
            geometry_msgs::TransformStamped transform_goal;
            geometry_msgs::PointStamped transformed_point;
            try {
                transform_goal = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
            } catch (tf2::TransformException& ex) {
                ROS_ERROR_THROTTLE(1.0, "Transform lookup failed: %s", ex.what());
                return;
            }
            tf2::doTransform(point_center, transformed_point, transform_goal);

            // loc bot nhung diem ben ngoai
            if (std::abs(transformed_point.point.y) < 0.5)
            {
                if (!linkLooked)
                {
                    link = lookupFixedFrameLink(scanStamp);
                    linkLooked = true;
                }
                // Time of the robot pose the outputs are expressed in, not now()
                ros::Time now = link.outStamp;

                // Filter the pallet CENTER pose (x, y, yaw) before broadcasting -> smooths
                // per-scan jitter/outliers so the control loop gets a stable input.
                double centerX = point_center.point.x;
                double centerY = point_center.point.y;
                double centerYaw = angleWith0x;
                filterPose2DInFixed(centerFilter_, centerX, centerY, centerYaw, scanStamp, link);

                // send frame of pallet
                static tf2_ros::TransformBroadcaster br1;
                static tf2_ros::TransformBroadcaster br2;
                static tf2_ros::TransformBroadcaster br3;
                geometry_msgs::TransformStamped transformStamped;
                transformStamped.header.stamp = now;
                transformStamped.header.frame_id = frameRobot_;
                transformStamped.child_frame_id = framePallet_;

                transformStamped.transform.translation.x = centerX;
                transformStamped.transform.translation.y = centerY;
                transformStamped.transform.translation.z = 0;

                tf2::Quaternion q1;
                q1.setRPY(0, 0, centerYaw);
                transformStamped.transform.rotation.x = q1.x();
                transformStamped.transform.rotation.y = q1.y();
                transformStamped.transform.rotation.z = q1.z();
                transformStamped.transform.rotation.w = q1.w();
                br1.sendTransform(transformStamped);

                if(useFrameUnder_)
                {
                    geometry_msgs::TransformStamped transformStamped1;
                    transformStamped1.header.stamp = now;
                    transformStamped1.header.frame_id = framePallet_;
                    transformStamped1.child_frame_id = framePalletUnder_;

                    transformStamped1.transform.translation.x = -0.6;
                    transformStamped1.transform.translation.y = 0.0;
                    transformStamped1.transform.translation.z = 0.0;
                    transformStamped1.transform.rotation.x = 0.0;
                    transformStamped1.transform.rotation.y = 0.0;
                    transformStamped1.transform.rotation.z = 0.0;
                    transformStamped1.transform.rotation.w = 1.0;
                    br2.sendTransform(transformStamped1);
                }

                if(publishEdgePallet_)
                {
                    // Filter the pallet EDGE pose independently of the center (own
                    // translation, same raw yaw measurement but its own Kalman state).
                    // double edgeX = line.firstPoint.point.x;
                    // double edgeY = line.firstPoint.point.y;
                    // Edge = center - width/2 along the line (towards the first point), not the
                    // measured first point: close up the ends lose points at shallow angles and
                    // the measured end moves inwards, while the midpoint stays put. Deriving the
                    // edge from the center and the known width keeps the two consistent.
                    const double fx = line.firstPoint.point.x, fy = line.firstPoint.point.y;
                    const double dx = line.lastPoint.point.x - fx, dy = line.lastPoint.point.y - fy;
                    const double len = std::hypot(dx, dy);
                    double edgeX = fx;
                    double edgeY = fy;
                    if (len > 1e-6)
                    {
                        edgeX = point_center.point.x - dx / len * 0.5 * lenghtPallet_;
                        edgeY = point_center.point.y - dy / len * 0.5 * lenghtPallet_;
                    }
                    double edgeYaw = angleWith0x;
                    filterPose2DInFixed(edgeFilter_, edgeX, edgeY, edgeYaw, scanStamp, link);

                    tf2::Quaternion q2;
                    q2.setRPY(0, 0, edgeYaw);

                    geometry_msgs::TransformStamped transformStamped2;
                    transformStamped2.header.stamp = now;
                    transformStamped2.header.frame_id = frameRobot_;
                    transformStamped2.child_frame_id = frameEdgePallet_;

                    transformStamped2.transform.translation.x = edgeX;
                    transformStamped2.transform.translation.y = edgeY;
                    transformStamped2.transform.translation.z = 0.0;
                    transformStamped2.transform.rotation.x = q2.x();
                    transformStamped2.transform.rotation.y = q2.y();
                    transformStamped2.transform.rotation.z = q2.z();
                    transformStamped2.transform.rotation.w = q2.w();
                    br2.sendTransform(transformStamped2);
                }
            }
        }
    }

    // Publish all visualization markers
    marker_array_pub_.publish(marker_array);
}

