    }

    // The tf buffer keeps the last detection for 10 s: without this check a lost
    // pallet keeps being republished as if it were current.
    double age = (ros::Time::now() - tf_child.header.stamp).toSec();
    if (age > maxTfAge_) {
        ROS_DEBUG_THROTTLE(1.0, "%s is stale (%.2f s old)", child.c_str(), age);
        return false;
    }

    // The Livox detection is only updated every few hundred ms. Carry the livox pose at
    // the detection's stamp to the robot's latest pose through fixedFrame_ (the frame the
    // pallet is still in). fixedFrame_ = odom: a pallet on the floor stays put while the
    // robot moves. fixedFrame_ = base_link: a carried pallet moves with the robot, the
    // chain is static and nothing is shifted.
    geometry_msgs::TransformStamped tf_robot_to_livox;
    try {
        tf_robot_to_livox = tf_buffer_->lookupTransform(frameRobot_, ros::Time(0),
                                                        "livox_frame", tf_child.header.stamp,
                                                        fixedFrame_, ros::Duration(tfTimeout_));
    } catch (tf2::TransformException& ex) {
        ROS_WARN_THROTTLE(1.0, "Motion compensation of %s via %s failed, using latest: %s",
                          child.c_str(), fixedFrame_.c_str(), ex.what());
        try {
            tf_robot_to_livox = tf_buffer_->lookupTransform(frameRobot_, "livox_frame", ros::Time(0), ros::Duration(tfTimeout_));
        } catch (tf2::TransformException& ex2) {
            ROS_ERROR_THROTTLE(1.0, "Transform failed (robot to livox): %s", ex2.what());
            return false;
        }
    }

    geometry_msgs::PoseStamped pose_in_livox;
    pose_in_livox.header = tf_child.header;
    pose_in_livox.pose.position.x = tf_child.transform.translation.x;
    pose_in_livox.pose.position.y = tf_child.transform.translation.y;
    pose_in_livox.pose.position.z = tf_child.transform.translation.z;
    pose_in_livox.pose.orientation = tf_child.transform.rotation;

    tf2::doTransform(pose_in_livox, poseRobot, tf_robot_to_livox);
    // Time of the robot pose the result is expressed in (now() if that chain is static)
    stamp = validStamp(tf_robot_to_livox.header.stamp);
    return true;
