void DectectObject::detectDistanceTwoLine3D() {
    ROS_INFO_THROTTLE(1.0, "======= Distance two line ======");
    std_msgs::Float64 msgDis;

    // Run once per new scan2 (was: block on waitForMessage every cycle)
    if (scan2Count_ == twoLine3dScan2Seen_)
        return;
    twoLine3dScan2Seen_ = scan2Count_;

    // 3D side = edge of the pallet carried on the forks (fixed_frame: base_link for this
    // node, no motion shift). A stale edge returns here, so the distance stops being
    // published and the placing server sees the sensor as lost instead of using old data.
    geometry_msgs::PoseStamped pallet_pose_in_robot;
    ros::Time stamp;
    if (!lookupLivoxPoseInRobot("pallet_edge_frame", pallet_pose_in_robot, stamp))
        return;

    // ===== Xử lý scan2 (giữ nguyên) =====
    std::vector<geometry_msgs::PointStamped> frameLaser2Points, frameMiddleLaser2Points;
    convertScanToPoint(scan2_, frameLaser2Points, scan2Frame_);
    if (!convertPointToNewFrame(scan2Frame_, frameLaserMiddleRobot_, frameLaser2Points, frameMiddleLaser2Points))
        return;

    filterPointMiddleRobot(frameMiddleLaser2Points);
    sortByAngle(frameMiddleLaser2Points);

    std::vector<geometry_msgs::PointStamped> frame2RobotPoints;
    if (!convertPointToNewFrame(frameLaserMiddleRobot_, frameRobot_, frameMiddleLaser2Points, frame2RobotPoints))
        return;

    if (frame2RobotPoints.size() < 20) {
        ROS_DEBUG_THROTTLE(1.0, "Không đủ điểm từ scan2_ (%zu điểm)", frame2RobotPoints.size());
        return;
    }

    double a2, b2, c2;
    linearRegression(frame2RobotPoints, a2, b2, c2);

    int count_error_2 = 0;
    for (const auto& pt : frame2RobotPoints) {
        double dis = distanceToLine(pt.point.x, pt.point.y, a2, b2, c2);
        if (dis > maxDiffCreatePath_) {
            count_error_2++;
            if (count_error_2 > 5) return;
        }
    }

    frame2RobotPoints.front() = getProjectionCoordinates(frame2RobotPoints.front(), a2, b2, c2);
    frame2RobotPoints.back()  = getProjectionCoordinates(frame2RobotPoints.back(),  a2, b2, c2);

    geometry_msgs::PointStamped point_center_2 = getPosCenter(frame2RobotPoints.front(), frame2RobotPoints.back());

    // Transform to base_link
    geometry_msgs::TransformStamped transform_to_base;
    try {
        transform_to_base = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
    } catch (tf2::TransformException& ex) {
        ROS_ERROR_THROTTLE(1.0, "Transform lookup failed (to base_link): %s", ex.what());
        return;
    }

    geometry_msgs::PointStamped center1_in_robot, center1_in_base, center2_in_base;
    center1_in_robot.header.frame_id = frameRobot_;
    center1_in_robot.point.x = pallet_pose_in_robot.pose.position.x;
    center1_in_robot.point.y = pallet_pose_in_robot.pose.position.y;
    center1_in_robot.point.z = 0.0;

    tf2::doTransform(center1_in_robot, center1_in_base, transform_to_base);
    tf2::doTransform(point_center_2, center2_in_base, transform_to_base);

    msgDis.data = center1_in_base.point.x - center2_in_base.point.x;
    distance_two_pallet_pub3d_.publish(msgDis);

    // Lấy yaw từ 3D và 2D
    double yaw1 = tf2::getYaw(pallet_pose_in_robot.pose.orientation) * 180.0 / M_PI;
    double yaw2 = std::atan2(-a2, b2) * 180.0 / M_PI;

    ROS_INFO_THROTTLE(1.0,
        "[3D+2D Distance] Pallet trái (3D): (%.3f, %.3f, %.1f deg) | "
        "Pallet phải (2D): (%.3f, %.3f, %.1f deg) | "
        "Khoảng cách: %.3f m",
        center1_in_base.point.x, center1_in_base.point.y, yaw1,
        center2_in_base.point.x, center2_in_base.point.y, yaw2,
        msgDis.data);
}

