// PCA / total least squares: minimizes the perpendicular distance, so any line
// direction works (the old y = bx + c fit broke on vertical lines).
// Result is a*y = b*x + c with a = cos(th), b = sin(th), th in (-90, 90] deg, so
// a >= 0 and atan2(-a, b) gives the same yaw branch as the old a = 1 fit.
void fit(double& a, double& b, double& c) const
{
    double mx = sumX / n;
    double my = sumY / n;
    double sxx = sumX2 / n - mx * mx;
    double syy = sumY2 / n - my * my;
    double sxy = sumXY / n - mx * my;
    double th = 0.5 * atan2(2.0 * sxy, sxx - syy);
    a = cos(th);
    b = sin(th);
    c = a * my - b * mx;
}

