void DectectObject::orientLine(double& a, double& b, double& c)
{
    if (!frameRobotRotValid_)
    {
        try {
            geometry_msgs::TransformStamped t = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
            tf2::fromMsg(t.transform.rotation, frameRobotRot_);
            frameRobotRotValid_ = true;
        } catch (tf2::TransformException& ex) {
            ROS_WARN_THROTTLE(1.0, "No base_link -> %s for the line direction: %s", frameRobot_.c_str(), ex.what());
            return;
        }
    }
    // direction of a*y = b*x + c is (a, b)
    tf2::Vector3 d = tf2::quatRotate(frameRobotRot_, tf2::Vector3(a, b, 0.0));
    if (cos(atan2(d.y(), d.x()) - lineDirRef_) < 0.0)
    {
        a = -a;
        b = -b;
        c = -c;
    }
}

