bool DectectObject::lookupFrameRobotRot()
{
    if (frameRobotRotValid_)
        return true;
    try {
        geometry_msgs::TransformStamped t = tf_buffer_->lookupTransform("base_link", frameRobot_, ros::Time(0), ros::Duration(tfTimeout_));
        tf2::fromMsg(t.transform.rotation, frameRobotRot_);
        frameRobotFlipped_ = tf2::quatRotate(frameRobotRot_, tf2::Vector3(0.0, 0.0, 1.0)).z() < 0.0;
        frameRobotRotValid_ = true;
    } catch (tf2::TransformException& ex) {
        ROS_WARN_THROTTLE(1.0, "No base_link -> %s for the line direction: %s", frameRobot_.c_str(), ex.what());
        return false;
    }
    return true;
}

void DectectObject::orientLine(double& a, double& b, double& c)
{
    if (!lookupFrameRobotRot())
        return;
    // direction of a*y = b*x + c is (a, b)
    tf2::Vector3 d = tf2::quatRotate(frameRobotRot_, tf2::Vector3(a, b, 0.0));
    bool flip = cos(atan2(d.y(), d.x()) - lineDirRef_) < 0.0;
    // The yaw atan2(-a, b) turns the direction by -90 deg about frameRobot_'s z. In a z-down
    // frame that is +90 deg in base_link, so take the opposite direction there to get the
    // same pallet heading as from a z-up frame.
    if (frameRobotFlipped_)
        flip = !flip;
    if (flip)
    {
        a = -a;
        b = -b;
        c = -c;
    }
}

tf2::Quaternion DectectObject::yawQuat(double yaw)
{
    lookupFrameRobotRot();
    tf2::Quaternion q;
    q.setRPY(frameRobotFlipped_ ? M_PI : 0.0, 0.0, yaw);
    return q;
}

