bool runDetect = false;
double pallet_size = 0.0;

bool setRunCallBack(pick_and_place_pallet::TriggerDetect::Request &req, pick_and_place_pallet::TriggerDetect::Response &res)
{
    pallet_size = req.pallet_size;
    runDetect = req.set_run;
    res.success = true;
    return true;
}

int main(int argc, char** argv)
{
    ros::init(argc, argv, "detect_object");
    ros::NodeHandle nh("~");
    detect_object::DectectObject detect(nh);
    ros::ServiceServer service = nh.advertiseService("call_detect_pallet", setRunCallBack);
    // 2D detectors no longer block in waitForMessage; they return at once unless a new
    // scan arrived, so poll faster to pick each scan up quickly. The 3D detectors only
    // re-publish the latest Livox TF, so keep them at the previous 20 Hz.
    ros::Rate r(50);
    const double period3d = 1.0 / 20.0;
    ros::Time last3d;
    while (ros::ok())
    {
        ros::spinOnce();
        bool run3d = false;
        if (detect.use3d_)
        {
            ros::Time now = ros::Time::now();
            run3d = (now - last3d).toSec() >= period3d || now < last3d;
            if (run3d)
                last3d = now;
        }

        if (runDetect == true && detect.useDetectPalletNormal_)
        {
            if (detect.use3d_)
            {
                if (run3d)
                    detect.detectObject3D();
            }
            else
            {
                detect.detectObject();
            }

            detect.lenghtPallet_ = pallet_size;
        }

        if (runDetect == true && detect.useDetectLineGo_)
        {
            if (!detect.use3d_)
            {
                detect.detectLineGo();
            }
            else if (run3d) {
                detect.detectLineGo3D();
            }
        }

        if (runDetect == true && detect.useDetectTwoLine_)
        {
            if (!detect.use3d_){
                detect.detectDistanceTwoLine();
            }
            else {
                detect.detectDistanceTwoLine3D();
            }
        }

        if (runDetect == true && detect.useDetectSquareCorner_)
        {
            if (!detect.use3d_){
                detect.detectSquareCorner();
            }

