    nh_priv.param<double>("laser_2_angle_pitch", laser_2_angle_pitch, 0.0);
    nh_priv.param<double>("laser_2_angle_yaw", laser_2_angle_yaw, 0.0);
    nh_priv.param<double>("distance_xylanh", distance_xylanh, 0.0);

    while (ros::ok())
    {
        ros::spinOnce();
        transformStamped1.header.stamp = ros::Time::now();
        transformStamped2.header.stamp = ros::Time::now();
        transformStamped3.header.stamp = ros::Time::now();
        transformStamped4.header.stamp = ros::Time::now();
        transformStamped5.header.stamp = ros::Time::now();
        transformStamped6.header.stamp = ros::Time::now();
        transformStamped_livox.header.stamp = ros::Time::now();  // Thêm dòng này
        // transformStamped1.transform.translation.y = laser_1_y + pose_fork_y;
        switch(control_olei_lidar_sensor){
            case 0:
                transformStamped1.transform.translation.y = laser_1_y;
                transformStamped_livox.transform.translation.y = livox_y;
                break;
            case 1:
                transformStamped1.transform.translation.y = laser_1_y + distance_xylanh;
                transformStamped_livox.transform.translation.y = livox_y + distance_xylanh;
                break;
            case 99:
                transformStamped1.transform.translation.y = laser_1_y;
                transformStamped_livox.transform.translation.y = livox_y;
                break;
        }

        br1.sendTransform(transformStamped1);
        br1.sendTransform(transformStamped2);
        br1.sendTransform(transformStamped3);
        br1.sendTransform(transformStamped4);
        br1.sendTransform(transformStamped5);
        br1.sendTransform(transformStamped6);
        br1.sendTransform(transformStamped_livox);  // Thêm dòng này
        ros::Duration(0.05).sleep();
    }
}





